// Swaps the six v1 webhooks onto the v2 URL and adds the two new projects.
const V2 = 'https://efuturemedia.app.n8n.cloud/webhook/lokalise-external-fill-v2';
const EVENTS = ['project.key.added', 'project.keys.added', 'project.translation.updated', 'project.translations.updated'];
const B = 'https://api.lokalise.com/api2/projects/';
// v1 webhook ids to remove
const OLD = [
  ['Mobitrace','14240418673f52ae29a007.74392007','a472871f3ef9efaf49af761f0b85e69a8af377bf'],
  ['Mobitrace - backend/emails','9274956467e3e224807498.79791832','534d93017280da2231731d4bc531bcf1b840d052'],
  ['My Image - Backend','50011170688b3050b0a7f8.40995136','e5d75d86a85785511d33dd93e3257fe1c2d584a8'],
  ['Unicopy','35679002689c4f3ba6dd50.31739712','d07c9b9c715dff4f0306144ccdad8bb81a66165e'],
  ['Unicopy (backend)','1600517668d38be7f36ba4.51132642','01a1bb85fa76954ea1b3c4df5e9825c270146254'],
  ['WAPP','4780438967fe077b4e6484.83742970','0845e3cfceed782dc4df1fdcdd736fcdbfca429d']
];
const ALL = [
  ['Mobitrace','14240418673f52ae29a007.74392007'],
  ['Mobitrace - backend/emails','9274956467e3e224807498.79791832'],
  ['My Image - Backend','50011170688b3050b0a7f8.40995136'],
  ['Unicopy','35679002689c4f3ba6dd50.31739712'],
  ['Unicopy (backend)','1600517668d38be7f36ba4.51132642'],
  ['WAPP','4780438967fe077b4e6484.83742970'],
  ['QRcreate','491848986923fad6dc2f85.42477363'],
  ['WAPP Backend (emails)','1274536968b58980dc56a0.78363786']
];
const out = [];
for (const o of OLD) { out.push({ json: { step: 'delete', name: o[0], method: 'DELETE', url: B + o[1] + '/webhooks/' + o[2], body: null } }); }
for (const a of ALL) { out.push({ json: { step: 'create', name: a[0], method: 'POST', url: B + a[1] + '/webhooks', body: { url: V2, events: EVENTS } } }); }
return out;

const reqs = $('Config').all();
const res = $input.all();
const delResults = [];
const creates = [];
for (let i = 0; i < reqs.length; i++) {
  const m = reqs[i].json;
  if (m.step === 'delete') {
    const r = (res[i] || { json: {} }).json || {};
    delResults.push({ project: m.name, status: r.statusCode });
  }
}
for (const q of reqs) { if (q.json.step === 'create') { creates.push({ json: { name: q.json.name, url: q.json.url, body: q.json.body, del: delResults } }); } }
return creates;

const reqs = $('Split Steps').all();
const res = $input.all();
const rows = [];
for (let i = 0; i < res.length; i++) {
  const m = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  const w = b.webhook || null;
  rows.push({ project: m.name, status: r.statusCode, webhook_id: w ? w.webhook_id : null, error: w ? null : JSON.stringify(b).slice(0, 200) });
}
return [{ json: { deleted: (reqs[0] || { json: {} }).json.del || [], created: rows } }];
